MIME-Version: 1.0
Content-Type: multipart/mixed; boundary="outer-1"

--outer-1
Content-Type: text/javascript; charset=utf-8
Content-Disposition: attachment; filename="fluid.demos.ai.imageByClosestNote"
Content-Description: layer

fluid.def("fluid.demos.ai.imageByClosestNote", {
    $layers: ["fluid.demos.imageGenerator", "fluid.topLevelWidget"],
    // The dominant widget is the image generator; the closest sticky note supplies its prompt. The finder shares
    // the root view, so neither it nor its descendants render, but its computation of the closest note carries on,
    // tracking the widget's bounds and every note on the canvas. Move this widget next to a note and press
    // "Find Image", and the note's text is used as the search prompt.
    finder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            view: "{imageByClosestNote}.view"
        }
    },
    state: {
        prompt: "{finder}.noteText"
    }
});
--outer-1
Content-Type: multipart/mixed; boundary="inner-1"
Content-Disposition: attachment; filename="shape:imageByClosestNote"
Content-Description: component

--inner-1
Content-Type: application/json; charset=utf-8
Content-Disposition: attachment; filename="/"
Content-Description: potentia

{
    "$layers": [
        "fluid.demos.ai.imageByClosestNote"
    ],
    "view": {
        "$component": {
            "shapeId": "shape:imageByClosestNote"
        }
    }
}
